import{_ as e,o as t,c as i,aw as a}from"./chunks/framework.DLufY-ao.js";const _=JSON.parse('{"title":"Сетевая модель OSI","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/network/network/protocols/osi.md","filePath":"wiki/dev-commit/network/network/protocols/osi.md"}'),l={name:"wiki/dev-commit/network/network/protocols/osi.md"};function r(n,o,s,c,P,d){return t(),i("div",null,[...o[0]||(o[0]=[a('<h1 id="сетевая-модель-osi" tabindex="-1">Сетевая модель OSI <a class="header-anchor" href="#сетевая-модель-osi" aria-label="Permalink to &quot;Сетевая модель OSI&quot;">​</a></h1><ul><li><strong>Сетевая модель OSI</strong> (The Open Systems Interconnection model) - сетевая модель стека (магазина) сетевых протоколов OSI/ISO. Посредством данной модели различные сетевые устройства могут взаимодействовать друг с другом. Модель определяет различные уровни взаимодействия систем. Каждый уровень выполняет определённые функции при таком взаимодействии.</li></ul><h2 id="уровни-модели-osi" tabindex="-1">Уровни модели OSI <a class="header-anchor" href="#уровни-модели-osi" aria-label="Permalink to &quot;Уровни модели OSI&quot;">​</a></h2><ol><li>Физический (physical) (Биты) - Работа со средой передачи, сигналами и двоичными данными. USB Кабели</li><li>Канальный (data link) (Биты / Кадры) - Физическая адресация. PPP IEEE 802.22 Ethernet DSL ARP Сетевая карта</li><li>Сетевой (network) (Пакеты) - Определение маршрута и логическая адресация. IPv4 IPv6 IPsec AppleTalk ICMP</li><li>Транспортный (transport) (Сегменты / Датаграммы) - Прямая связь между конечными пунктами и надёжность. TCP UDP SCTP PORTS</li><li>Сеансовый (session) (Данные) - Управление сеансом связи. RPC PAP L2TP</li><li>Представления (presentation) (Данные) - Представление и шифрование данных. ASCII EBCDIC</li><li>Прикладной (application) (Данные) - Доступ к сетевым службам. HTTP FTP POP3 WebSocket</li></ol>',4)])])}const S=e(l,[["render",r]]);export{_ as __pageData,S as default};
